CREATE FUNCTION gridex_ediel_ack_guide.projection_for_original_v1(p_source_version text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE original jsonb;extended jsonb;
BEGIN
 SELECT projection INTO STRICT original FROM gridex_ediel_ack_guide.editions WHERE source_version=p_source_version;
 IF original ? 'registeredGuideScopes' THEN RETURN original;END IF;
 SELECT e.projection INTO extended FROM gridex_ediel_ack_guide.edition_extensions x JOIN gridex_ediel_ack_guide.editions e ON e.source_version=x.extended_source_version WHERE x.original_source_version=p_source_version;
 IF extended IS NULL OR extended->'constraints' IS DISTINCT FROM original->'constraints' OR extended->'originalSources' IS DISTINCT FROM original->'originalSources' THEN RAISE EXCEPTION 'ediel_registered_original_guide_unavailable';END IF;
 RETURN extended;
END $$;
CREATE FUNCTION gridex_ediel_ack_guide.require_registered_basis_v1(m public.ediel_messages,p_kind text,p_basis jsonb,p_projection jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE r jsonb;v text;n integer;
BEGIN
 -- The protected syntax-only CONTRL owner has no business pack and cannot
 -- acquire one from this scope projection. Its technical edition stays bound.
 IF p_kind='technical' THEN RETURN;END IF;
 IF p_kind='common' THEN r:=p_basis#>'{familyEdition,rulePack}';v:=p_basis#>>'{familyEdition,version}';ELSE r:=p_basis#>'{snapshot,rulePack}';v:=p_basis->>'version';END IF;
 IF r IS NULL OR r->>'family' IS DISTINCT FROM m.message_family OR nullif(v,'') IS NULL THEN RAISE EXCEPTION 'ediel_registered_original_guide_unavailable';END IF;
 SELECT count(*) INTO n FROM jsonb_array_elements(p_projection->'registeredGuideScopes')s WHERE s->>'family'=r->>'family' AND s->>'guideVersion'=r->>'guide_version' AND s->>'guideRevision'=r->>'guide_revision' AND s->>'version'=v;
 IF n<>1 THEN RAISE EXCEPTION 'ediel_registered_original_guide_unavailable';END IF;
END $$;
ALTER FUNCTION gridex_ediel_ack_guide.bind_source_v1(public.ediel_messages,text,jsonb) RENAME TO bind_source_before_registered_scope_v1;
CREATE FUNCTION gridex_ediel_ack_guide.bind_source_v1(m public.ediel_messages,p_kind text,p_basis jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE b gridex_ediel_ack_guide.source_bindings%rowtype;
BEGIN
 PERFORM gridex_ediel_ack_guide.bind_source_before_registered_scope_v1(m,p_kind,p_basis);
 SELECT * INTO STRICT b FROM gridex_ediel_ack_guide.source_bindings WHERE source_message_id=m.id AND kind=p_kind;
 PERFORM gridex_ediel_ack_guide.require_registered_basis_v1(m,p_kind,p_basis,gridex_ediel_ack_guide.projection_for_original_v1(b.source_version));
END $$;
CREATE FUNCTION gridex_ediel_ack_guide.validate_utilts_err_v1(p_raw text,p_source_raw text,p_projection jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE tokens jsonb:=gridex_utilts_binding.wire_tokens_v1(p_raw);original jsonb:=gridex_utilts_binding.wire_tokens_v1(p_source_raw);a jsonb:=gridex_ack_authority.wire_v1(p_raw);s jsonb:=gridex_ack_authority.wire_v1(p_source_raw);cfg jsonb:=p_projection->'utiltsErr';t jsonb;source_token jsonb;field jsonb;e jsonb;actual jsonb;expected jsonb;header_end integer;source_header_end integer;group_start integer;group_end integer;source_start integer;source_end integer;seq integer;n integer;tx text;own_id text;reason text;ids text[]:='{}';answered text[]:='{}';opposite text;qualifier text;
BEGIN
 IF tokens IS NULL OR original IS NULL OR a IS NULL OR s IS NULL OR cfg IS NULL OR cfg->>'version'<>'1' OR a->>'family'<>'UTILTS' OR a->>'code'<>'ERR' OR s->>'family'<>'UTILTS' OR NOT coalesce(cfg->'originalMessageCodes' ? (s->>'code'),false) OR NOT coalesce(gridex_ack_authority.source_match_v1(a,s),false) THEN RETURN false;END IF;
 IF a->'type' IS DISTINCT FROM cfg->'technicalProfile' OR a->'type' IS DISTINCT FROM s->'type' OR EXISTS(SELECT FROM jsonb_array_elements(tokens)x WHERE cfg->'forbiddenSegments' ? (x->>'tag')) THEN RETURN false;END IF;
 SELECT count(*),min((x->>'index')::int) INTO n,header_end FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='IDE';IF n=0 THEN RETURN false;END IF;
 SELECT min((x->>'index')::int) INTO source_header_end FROM jsonb_array_elements(original)x WHERE x->>'tag'='IDE';IF source_header_end IS NULL THEN RETURN false;END IF;
 SELECT count(*) INTO n FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='BGM';IF n<>1 THEN RETURN false;END IF;
 SELECT x->'elements' INTO e FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='BGM';
 IF e#>>'{1,0}' IS DISTINCT FROM cfg->>'documentCode' OR e#>>'{1,2}' IS DISTINCT FROM cfg->>'documentAgency' OR NOT coalesce(cfg->'optionalDocumentCodeLists' ? coalesce(e#>>'{1,1}',''),false) OR gridex_ediel_ack_guide.tail_populated_v1(e->1,3) OR nullif(e#>>'{2,0}','') IS NULL OR length(e#>>'{2,0}')>(cfg->>'documentIdMax')::int OR jsonb_array_length(e->2)<>1 OR NOT coalesce(cfg->'allowedFunctions' ? (e#>>'{3,0}'),false) OR NOT coalesce(cfg->'allowedAcknowledgementRequests' ? (e#>>'{4,0}'),false) OR jsonb_array_length(e->3)<>1 OR jsonb_array_length(e->4)<>1 OR jsonb_array_length(e)>5 THEN RETURN false;END IF;
 SELECT count(*) INTO n FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='DTM' AND x#>>'{elements,1,0}'=cfg#>>'{documentDate,qualifier}' AND(x->>'index')::int<header_end;IF n<>1 THEN RETURN false;END IF;
 SELECT x#>'{elements,1}' INTO e FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='DTM' AND x#>>'{elements,1,0}'=cfg#>>'{documentDate,qualifier}' AND(x->>'index')::int<header_end;
 IF jsonb_array_length(e)<>3 OR e->>2 IS DISTINCT FROM cfg#>>'{documentDate,format}' OR NOT coalesce(gridex_ediel_ack_guide.date_time_v1(e->>1),false) THEN RETURN false;END IF;
 SELECT count(*) INTO n FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='DTM' AND x#>>'{elements,1,0}'='735' AND(x->>'index')::int<header_end;IF n<>1 THEN RETURN false;END IF;
 SELECT x#>'{elements,1}' INTO e FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='DTM' AND x#>>'{elements,1,0}'='735' AND(x->>'index')::int<header_end;IF e IS DISTINCT FROM cfg->'fixedOffset' THEN RETURN false;END IF;
 SELECT count(*) INTO n FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='MKS' AND(x->>'index')::int<header_end;IF n<>1 THEN RETURN false;END IF;
 SELECT x->'elements' INTO actual FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='MKS' AND(x->>'index')::int<header_end;
 SELECT count(*) INTO n FROM jsonb_array_elements(original)x WHERE x->>'tag'='MKS' AND(x->>'index')::int<source_header_end;IF n<>1 THEN RETURN false;END IF;
 SELECT x->'elements' INTO expected FROM jsonb_array_elements(original)x WHERE x->>'tag'='MKS' AND(x->>'index')::int<source_header_end;
 IF actual IS DISTINCT FROM expected OR NOT coalesce(cfg->'marketCodes' ? (actual#>>'{1,0}'),false) OR NOT coalesce(cfg->'phaseCodes' ? (actual#>>'{2,0}'),false) OR actual#>>'{2,2}' IS DISTINCT FROM cfg->>'agency' THEN RETURN false;END IF;
 FOREACH qualifier IN ARRAY ARRAY['MS','MR'] LOOP
  SELECT count(*) INTO n FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'=qualifier AND(x->>'index')::int<header_end;IF n<>1 THEN RETURN false;END IF;
  SELECT x#>'{elements,2}' INTO e FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'=qualifier AND(x->>'index')::int<header_end;
  IF nullif(e->>0,'') IS NULL OR length(e->>0)>35 OR NOT coalesce(cfg->'legalAgencies' ? (e->>2),false) OR (e->>2=cfg->>'svkAgency' AND e->>1 IS DISTINCT FROM cfg->>'svkQualifier') THEN RETURN false;END IF;
  IF e->>1=cfg#>>'{identity,edielQualifier}' AND (e->>0)!~(cfg#>>'{identity,edielIdPattern}') THEN RETURN false;END IF;
  IF cfg#>'{identity,gs1Agencies}' ? (e->>2) THEN
   IF (e->>0)!~(cfg#>>'{identity,glnPattern}') OR (SELECT sum(substr(e->>0,i,1)::int*(cfg#>'{identity,glnCheckWeights}'->>((i-1)%jsonb_array_length(cfg#>'{identity,glnCheckWeights}')))::int)%10 FROM generate_series(1,length(e->>0))i)<>0 THEN RETURN false;END IF;
  END IF;
 END LOOP;
 SELECT count(*) INTO n FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}' NOT IN('MS','MR') AND(x->>'index')::int<header_end;IF n<>1 THEN RETURN false;END IF;
 SELECT x->'elements' INTO actual FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}' NOT IN('MS','MR') AND(x->>'index')::int<header_end;
 SELECT count(*) INTO n FROM jsonb_array_elements(original)x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}' NOT IN('MS','MR') AND(x->>'index')::int<source_header_end;IF n<>1 THEN RETURN false;END IF;
 SELECT x->'elements' INTO expected FROM jsonb_array_elements(original)x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}' NOT IN('MS','MR') AND(x->>'index')::int<source_header_end;
 IF actual IS DISTINCT FROM expected OR NOT coalesce(cfg->'subordinateRoles' ? (actual#>>'{1,0}'),false) OR EXISTS(SELECT FROM jsonb_array_elements(actual)WITH ORDINALITY z(e,n) WHERE z.n>2 AND gridex_ediel_ack_guide.tail_populated_v1(z.e,0)) THEN RETURN false;END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='IDE' ORDER BY(x->>'index')::int LOOP
  group_start:=(t->>'index')::int;SELECT min((x->>'index')::int) INTO group_end FROM jsonb_array_elements(tokens)x WHERE(x->>'index')::int>group_start AND x->>'tag' IN('IDE','UNT','UNZ');IF group_end IS NULL THEN RETURN false;END IF;
  own_id:=t#>>'{elements,2,0}';IF t#>'{elements,1}' IS DISTINCT FROM jsonb_build_array(cfg->>'transactionQualifier') OR t#>'{elements,2}' IS DISTINCT FROM jsonb_build_array(own_id) OR nullif(own_id,'') IS NULL OR length(own_id)>(cfg->>'ownTransactionIdMax')::int OR own_id=ANY(ids) THEN RETURN false;END IF;ids:=array_append(ids,own_id);
  SELECT count(*) INTO n FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='STS' AND x#>>'{elements,1,0}'=cfg->>'responseQualifier' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;IF n<>1 THEN RETURN false;END IF;
  SELECT x->'elements' INTO e FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='STS' AND x#>>'{elements,1,0}'=cfg->>'responseQualifier' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;reason:=e#>>'{3,0}';
  IF e->1 IS DISTINCT FROM jsonb_build_array(cfg->>'responseQualifier','',cfg->>'agency') OR e->2 IS DISTINCT FROM jsonb_build_array(cfg->>'responseStatus') OR e->3 IS DISTINCT FROM jsonb_build_array(reason,'',cfg->>'agency') OR NOT coalesce(cfg->'allowedReasons' ? reason,false) OR jsonb_array_length(e)>4 THEN RETURN false;END IF;
  SELECT count(*) INTO n FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'=cfg->>'referenceQualifier' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;IF n<>1 THEN RETURN false;END IF;
  SELECT x#>'{elements,1}' INTO e FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'=cfg->>'referenceQualifier' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;tx:=e->>1;
  IF e IS DISTINCT FROM jsonb_build_array(cfg->>'referenceQualifier',tx) OR nullif(tx,'') IS NULL OR length(tx)>(cfg->>'originalTransactionIdMax')::int OR (tx||'|'||reason)=ANY(answered) THEN RETURN false;END IF;answered:=array_append(answered,tx||'|'||reason);
  IF EXISTS(SELECT FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}' NOT IN(cfg->>'referenceQualifier',s->>'code') AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end) THEN RETURN false;END IF;
  SELECT count(*) INTO n FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'=s->>'code' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;IF n<>1 THEN RETURN false;END IF;
  SELECT x#>'{elements,1}' INTO e FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'=s->>'code' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;IF e IS DISTINCT FROM jsonb_build_array(s->>'code',s->>'document') THEN RETURN false;END IF;
  SELECT count(*) INTO n FROM jsonb_array_elements(original)x WHERE x->>'tag'='IDE' AND x#>>'{elements,1,0}'=cfg->>'transactionQualifier' AND x#>>'{elements,2,0}'=tx;IF n<>1 THEN RETURN false;END IF;
  SELECT(x->>'index')::int INTO source_start FROM jsonb_array_elements(original)x WHERE x->>'tag'='IDE' AND x#>>'{elements,1,0}'=cfg->>'transactionQualifier' AND x#>>'{elements,2,0}'=tx;
  SELECT min((x->>'index')::int) INTO source_end FROM jsonb_array_elements(original)x WHERE(x->>'index')::int>source_start AND x->>'tag' IN('IDE','UNT','UNZ');SELECT min((x->>'index')::int) INTO seq FROM jsonb_array_elements(original)x WHERE x->>'tag'='SEQ' AND(x->>'index')::int>source_start AND(x->>'index')::int<source_end;source_end:=coalesce(seq,source_end);
  FOR field IN SELECT x FROM jsonb_array_elements(p_projection->'utiltsErrSourceCopyFields')x LOOP
   SELECT jsonb_agg(x->'elements' ORDER BY(x->>'index')::int) INTO expected FROM jsonb_array_elements(original)x WHERE x->>'tag'=field->>'tag' AND x#>>'{elements,1,0}'=field->>'qualifier' AND(x->>'index')::int>source_start AND(x->>'index')::int<source_end;
   SELECT jsonb_agg(x->'elements' ORDER BY(x->>'index')::int) INTO actual FROM jsonb_array_elements(tokens)x WHERE x->>'tag'=field->>'tag' AND x#>>'{elements,1,0}'=field->>'qualifier' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;
   IF coalesce(actual,'[]') IS DISTINCT FROM coalesce(expected,'[]') THEN RETURN false;END IF;
  END LOOP;
 END LOOP;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
ALTER FUNCTION gridex_ediel_ack_guide.validate_v1(text,text,jsonb) RENAME TO validate_before_registered_responses_v1;
CREATE FUNCTION gridex_ediel_ack_guide.validate_v1(p_raw text,p_source_raw text,p_projection jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE a jsonb:=gridex_ack_authority.wire_v1(p_raw);
BEGIN IF a->>'family'='UTILTS' AND a->>'code'='ERR' THEN RETURN gridex_ediel_ack_guide.validate_utilts_err_v1(p_raw,p_source_raw,p_projection);END IF;RETURN gridex_ediel_ack_guide.validate_before_registered_responses_v1(p_raw,p_source_raw,p_projection);END $$;
CREATE OR REPLACE FUNCTION gridex_ediel_ack_guide.require_v1(m public.ediel_messages) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE source public.ediel_messages%rowtype;b gridex_ediel_ack_guide.source_bindings%rowtype;projection jsonb;basis jsonb;binding_kind text;observed timestamptz:=clock_timestamp();stamp text;document_at timestamptz;
BEGIN
 IF m.message_family NOT IN('APERAK','CONTRL','UTILTS_ERR') THEN RETURN;END IF;
 binding_kind:=CASE WHEN m.message_family='CONTRL' THEN 'technical' WHEN m.execution_context_snapshot->>'prodatCommonHeaderNegativeWitnessId' IS NOT NULL THEN 'common' ELSE 'national' END;
 SELECT * INTO source FROM public.ediel_messages WHERE id=m.related_message_id AND (company_id=m.company_id OR (binding_kind IN('technical','common') AND company_id IS NULL)) AND environment=m.environment AND direction='inbound' FOR SHARE;IF source.id IS NULL THEN RAISE EXCEPTION 'ediel_native_ack_guide_source_required';END IF;
 basis:=CASE binding_kind WHEN 'technical' THEN gridex_ediel_technical_ack.require_source_v1(m.company_id,source.id) WHEN 'common' THEN gridex_ediel_common_header.require_ack_v1(m) ELSE gridex_ediel_source_rules.require_v1(m.company_id,source.id) END;
 SELECT * INTO b FROM gridex_ediel_ack_guide.source_bindings WHERE source_message_id=source.id AND kind=binding_kind FOR SHARE;IF b.source_message_id IS NULL THEN RAISE EXCEPTION 'ediel_historical_ack_guide_basis_unavailable';END IF;
 IF b.company_id IS DISTINCT FROM m.company_id OR b.environment IS DISTINCT FROM m.environment OR b.payload_sha256 IS DISTINCT FROM encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex') OR b.original_basis IS DISTINCT FROM basis THEN RAISE EXCEPTION 'ediel_ack_guide_original_basis_changed';END IF;
 projection:=gridex_ediel_ack_guide.projection_for_original_v1(b.source_version);PERFORM gridex_ediel_ack_guide.require_registered_basis_v1(source,binding_kind,basis,projection);
 IF NOT coalesce(gridex_ediel_ack_guide.validate_v1(m.raw_payload,source.raw_payload,projection),false) THEN RAISE EXCEPTION 'ediel_native_ack_guide_invalid';END IF;
 IF m.message_family='UTILTS_ERR' AND projection#>>'{utiltsErr,documentDate,noFuture}'='true' THEN
  SELECT x#>>'{elements,1,1}' INTO stamp FROM jsonb_array_elements(gridex_utilts_binding.wire_tokens_v1(m.raw_payload))x WHERE x->>'tag'='DTM' AND x#>>'{elements,1,0}'=projection#>>'{utiltsErr,documentDate,qualifier}';
  document_at:=(make_timestamp(substr(stamp,1,4)::int,substr(stamp,5,2)::int,substr(stamp,7,2)::int,substr(stamp,9,2)::int,substr(stamp,11,2)::int,0) AT TIME ZONE 'UTC')-interval '1 hour';IF document_at>observed THEN RAISE EXCEPTION 'ediel_native_err_document_date_future';END IF;
 END IF;
END $$;
-- Existing sealed INSERT and generic/H new-entry wrappers already call the
-- shared require_v1. Extend fresh witness preparation to ERR as well; established
-- accepted/entered/provider observations keep their earlier immutable return.
ALTER FUNCTION gridex_ediel_outbound_owner.prepare_v1(jsonb) RENAME TO prepare_before_registered_responses_v1;
CREATE FUNCTION gridex_ediel_outbound_owner.prepare_v1(p_input jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE m public.ediel_messages%rowtype;a jsonb;
BEGIN a:=gridex_ack_authority.wire_v1(p_input->>'rawPayload');IF a->>'family'='UTILTS' AND a->>'code'='ERR' THEN m.company_id:=(p_input->>'companyId')::uuid;m.environment:=p_input->>'environment';m.direction:='outbound';m.message_family:='UTILTS_ERR';m.message_code:='ERR';m.raw_payload:=p_input->>'rawPayload';m.related_message_id:=(p_input->>'relatedMessageId')::uuid;PERFORM gridex_ediel_ack_guide.require_v1(m);END IF;RETURN gridex_ediel_outbound_owner.prepare_before_registered_responses_v1(p_input);END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA gridex_ediel_ack_guide FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION gridex_ediel_outbound_owner.prepare_before_registered_responses_v1(jsonb),gridex_ediel_outbound_owner.prepare_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION gridex_ediel_outbound_owner.prepare_v1(jsonb) TO service_role;
COMMIT;
